import { appendFileSync } from 'node:fs';
import { createRequire } from 'node:module';
const coreRequire = createRequire(process.env.MANAGED_CORE_PACKAGE);
const pa11yRequire = createRequire(coreRequire.resolve('pa11y/package.json'));
const puppeteer = pa11yRequire('puppeteer');
const realLaunch = puppeteer.launch;
const record = (event) => appendFileSync(process.env.MANAGED_BROWSER_LAUNCH_TRACE, JSON.stringify(event) + '\n');
puppeteer.launch = async function (...args) {
  record({ event: 'launch-request', node: process.version, executablePath: args[0]?.executablePath, environmentExecutablePath: process.env.PUPPETEER_EXECUTABLE_PATH ?? null });
  const browser = await realLaunch.apply(this, args);
  const child = browser.process();
  record({ event: 'browser-launched', pid: child?.pid, spawnfile: child?.spawnfile, version: await browser.version() });
  browser.once('disconnected', () => record({ event: 'browser-disconnected', pid: child?.pid }));
  return browser;
};
